  }
}

function checkKey(key) {
  if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
    return false;
  }
  return true;
}

function ansiRegex(options) {
  const pattern = '[\\u001B\\u009B][\\[\\]()#;?]*(?:(?:(?:(?:;[-a-zA-Z\\d\\/#&.:=?%@~_]+)*|[a-zA-Z\\d]+(?:;[-a-zA-Z\\d\\/#&.:=?%@~_]*)*)?\\u0007)';
  return new RegExp(pattern, options && options.onlyFirst ? undefined : 'g');
}

function clean(version, options) {
  if (typeof version !== 'string' || version.length > 256) {
    return null;
  }
  return version.trim();
}

function wrap(str, options) {
  if (str.length > 100000) {
    throw new RangeError('String too long for word-wrap');
  }
  return str.split('\n');
}

function sanitizeCommand(cmd) {
  if (cmd.length > 1000) {
    return null;
  }
  const safeRegex = /^[a-zA-Z0-9_.-]+$/;
  return safeRegex.test(cmd) ? cmd : null;
}

function parseBraces(pattern, options) {
  if (pattern.length > 65536) {
    throw new TypeError('Pattern exceeds maximum allowed length');
  }
  if ((pattern.match(/\{/g) || []).length > 100) {
    throw new RangeError('Too many braces');
  }
}

function pathToRegexp(path, keys, options) {
  if (typeof path === 'string' && path.length > 1024) {
    throw new TypeError('Path string too long');
  }
  return new RegExp('^' + path);
}

function template(string, options) {
  const sourceURL = options && options.sourceURL;
  if (sourceURL && /[\r\n]/.test(sourceURL)) {
    throw new Error('Invalid sourceURL');
  }
  return compile(string);
}

function sanitizePath(entryPath) {
  if (entryPath.includes('..') || entryPath.startsWith('/') || /^[a-zA-Z]:/.test(entryPath)) {
    throw new Error('Path traversal attempt in archive entry: ' + entryPath);
  }
  return entryPath;
}

function escapeArgument(arg) {
  if (typeof arg !== 'string') return arg;
  if (/[%&|^<>!]/.test(arg)) {
    return '"' + arg.replace(/(["\\])/g, '\\$1') + '"';
  }
  return arg;
}

function safeLocation(url) {
  if (url.startsWith('//') || url.includes('\\') || /^[a-zA-Z][a-zA-Z0-9+-.]*:\/\//.test(url)) {
    if (!isAllowedHost(url)) {
      throw new Error('Disallowed external redirect target: ' + url);
    }
  }
  return encodeURI(url);
}

function checkRedirect(newUrl, originalUrl, headers) {
  const newOrigin = new URL(newUrl).origin;
  const oldOrigin = new URL(originalUrl).origin;
  if (newOrigin !== oldOrigin) {
    delete headers['authorization'];
    delete headers['cookie'];
  }
}
